function addFooter(doc){


    const pageCount =
    doc.getNumberOfPages();


    for(
        let i = 1;
        i <= pageCount;
        i++
    ){

        doc.setPage(i);


        doc.setFontSize(9);


        doc.text(

            "Smart Safety Vest Monitoring System",

            20,

            285

        );


        doc.text(

            "Generated by: Admin",

            80,

            285

        );


        doc.text(

            "Page "
            +
            i
            +
            " of "
            +
            pageCount,

            160,

            285

        );


        doc.line(

            20,

            278,

            190,

            278

        );


    }


}

