let safetyStatus = "SAFE";

let reasons = [];


// Fall check

if(fallCount > 0)
{

    safetyStatus = "WARNING";

    reasons.push(
        "Fall event detected"
    );

}



// Gas check

if(maxGas > 400)
{

    safetyStatus = "WARNING";

    reasons.push(
        "High gas level detected"
    );

}



// Temperature check

if(maxTemperature > 40)
{

    safetyStatus = "WARNING";

    reasons.push(
        "High temperature detected"
    );

}



doc.autoTable({

    startY:40,


    head:[

        [
            "Status",
            "Details"
        ]

    ],


    body:[

        [
            safetyStatus,
            reasons.length
            ?
            reasons.join(", ")
            :
            "Worker monitoring normal"
        ]

    ]

});



